def angle_diff(target, cur):
    return (target - cur + 180) % 360 - 180

def turn_to(target):
    while True:
        e = angle_diff(target, heading())
        if abs(e) < 9:
            break
        if abs(e) > 30:
            p = 0.25
        else:
            p = 0.1
        if e > 0:
            motor(p, -p)
        else:
            motor(-p, p)
    stop()
    wait(0.3)

# 1. 近い向きへ回る（9° 以内まで）
turn_to(TARGET)
# 2. 残りの角度を 5 回測って平均し、時間で回る（差 0.2 は 1 秒に約 78°）
total = 0
for i in range(5):
    total = total + angle_diff(TARGET, heading())
e = total / 5
if e > 0:
    motor(0.1, -0.1)
else:
    motor(-0.1, 0.1)
wait(abs(e) / 77.8)
stop()
wait(0.3)
# 3. コーンへ走って、LiDAR で止まる
motor(0.6, 0.6)
while True:
    d = lidar()
    if d is not None and d < 0.25:
        break
