def angle_diff(target, cur):
    return (target - cur + 180) % 360 - 180

# 1. 向きを変える道具
def turn_to(target):
    while True:
        e = angle_diff(target, heading())
        if abs(e) < 9:
            break
        if abs(e) > 30:
            p = 0.25
        else:
            p = 0.1
        if e > 0:
            motor(p, -p)
        else:
            motor(-p, p)
    stop()
    wait(0.3)

# 2. まっすぐ走る道具（PI 制御）
def straight(target, meters):
    total = 0
    t_prev = now()
    start = odometer()
    while odometer() - start < meters - 0.1:
        e = angle_diff(target, heading())
        t = now()
        total = total + e * (t - t_prev)
        t_prev = t
        turn = 0.02 * e + 0.02 * total
        if turn > 0.3:
            turn = 0.3
        if turn < -0.3:
            turn = -0.3
        motor(0.7 + turn, 0.7 - turn)
    stop()
    wait(0.3)

# 3. 4 つの辺を走る
for target in [0, 90, 180, 270]:
    turn_to(target)
    straight(target, 4.0)

